    const ctx = canvas.getContext("2d");

    // Draw the torus and sphere
    function drawTorus(radius, majorRadius, minorRadius) {
        const r = minorRadius;
        const R = majorRadius;
        const r_inner = r + R;
        const r_outer = r - R;

        const angle = 0.5;
        const x = r_inner * Math.cos(angle);
        const y = r_inner * Math.sin(angle);

        ctx.beginPath();
        ctx.arc(x, y, r_inner, 0, 2 * Math.PI);
        ctx.stroke();

        ctx.beginPath();
        ctx.arc(x, y, r_outer, 0, 2 * Math.PI);
        ctx.stroke();
    }

    function drawSphere(radius) {
        const r = radius;
        const x = 0;
        const y = 0;
        const z = r;

        ctx.beginPath();
        ctx.arc(x, y, z, 0, 2 * Math.PI);
        ctx.stroke();
    }

    // Set up the canvas size
    canvas.width = 400;
    canvas.height = 400;

    // Draw the torus
    drawTorus(3, 9, 3);

    // Draw the sphere
    drawSphere(11);

    // Set up the coordinate system
    ctx.translate(200, 200);
    ctx.rotate(Math.PI / 4);

    // Draw the torus and sphere again, but this time with the correct orientation
    drawTorus(3, 9, 3);
    drawSphere(11);

    // Reset the canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
});

